<?php
declare(strict_types=1);
namespace App\Services;
final class UploadGuard {public const LIST_MIMES=['text/plain','text/csv','application/pdf','application/msword','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'];public function storeList(array $file,string $dir):array{return $this->store($file,$dir,self::LIST_MIMES,5242880);}public function storeImage(array $file,string $dir):array{return $this->store($file,$dir,['image/jpeg','image/png','image/gif','image/webp'],10485760);}private function store(array $file,string $dir,array $mimes,int $max):array{if(($file['error']??4)!==0||($file['size']??0)>$max)throw new \RuntimeException('Arquivo inválido ou maior que o permitido.');$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);if(!in_array($mime,$mimes,true))throw new \RuntimeException('Tipo de arquivo não permitido.');if(!is_dir($dir))mkdir($dir,0700,true);$path=$dir.'/'.bin2hex(random_bytes(16)).'.'.strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));if(!move_uploaded_file($file['tmp_name'],$path))throw new \RuntimeException('Falha ao armazenar arquivo.');return[$path,$mime];}}
